export const TOOLS_BY_CATEGORY = new Map(
  CATEGORIES.map(cat => [
    cat.id,
    TOOLS.filter(t => t.category === cat.id)
  ])
);

export const TOOL_MAP = new Map(TOOLS.map(t => [t.id, t]));

export function findToolById(id: string): ToolDefinition | undefined {
  return TOOL_MAP.get(id);
}

export function getToolsByCategory(categoryId: string): ToolDefinition[] {
  return TOOLS_BY_CATEGORY.get(categoryId as any) || [];
}
